<?php declare(strict_types=1);require_once __DIR__.'/security.php';$u=portal_require_user();$id=(int)($_GET['id']??0);$q=$db->prepare('SELECT id,name,file_path FROM client_portal_documents WHERE id=? AND client_id=? AND is_visible=1 LIMIT 1');$q->execute([$id,(int)$u['client_id']]);$doc=$q->fetch();if(!$doc){http_response_code(404);exit('Document not found.');}$base=realpath(__DIR__.'/../storage/client-documents');$file=realpath($doc['file_path']);if(!$base||!$file||strncmp($file,$base.DIRECTORY_SEPARATOR,strlen($base.DIRECTORY_SEPARATOR))!==0||!is_file($file)){http_response_code(404);exit('File unavailable.');}portal_log((int)$u['client_id'],(int)$u['id'],'document_download','document',$id,$doc['name']);header('Content-Type: application/octet-stream');header('Content-Length: '.filesize($file));header('Content-Disposition: attachment; filename="'.basename($doc['name']).'"');readfile($file);exit;